                m |= (1 << i);
            }
        }
        if (ok) valid.push([x, m]);
    }

    const dp = new Array(1 << 10).fill(0n);
    dp[0] = 1n;

    for (const [x, mask] of valid) {
        const cnt = BigInt(freq[x]);
        for (let state = (1 << 10) - 1; state >= 0; state--) {
            if ((state & mask) === 0) {
                dp[state | mask] = (dp[state | mask] + dp[state] * cnt) % MOD;
            }
        }
    }

    let total = 0n;
    for (let s = 1; s < (1 << 10); s++) total = (total + dp[s]) % MOD;

    let p2 = 1n;
    for (let i = 0; i < freq[1]; i++) p2 = (p2 * 2n) % MOD;
    return Number((total * p2) % MOD);
